enum Payment {
  Cash,
  CreditCard(number: Str),
  Crypto(coin: Str),
}

fn describe_payment(payment: Payment) -> Str {
  return match payment {
    Cash => "Paid with cash",
    CreditCard(number) => "Paid with card: " + number,
    Crypto(coin) => "Paid with crypto: " + coin,
  };
}

fn get_identifier(payment: Payment) -> Str {
  return match payment {
    Cash => "N/A",
    CreditCard(number) => number,
    Crypto(coin) => coin,
  };
}

fn main() -> Int {
  io.println(describe_payment(Payment.Cash));
  io.println(get_identifier(Payment.CreditCard("7890")));
  io.println(get_identifier(Payment.Crypto("Solana")));
  return 0;
}
